const row = $input.first().json;

function firstValue(keys, fallback = '') {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') {
      return String(row[key]).trim();
    }
  }
  return fallback;
}

function extractDriveFileId(value) {
  const text = String(value || '');
  const patterns = [
    /\/file\/d\/([a-zA-Z0-9_-]+)/,
    /[?&]id=([a-zA-Z0-9_-]+)/,
    /open\?id=([a-zA-Z0-9_-]+)/,
    /uc\?id=([a-zA-Z0-9_-]+)/
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) return match[1];
  }
  const rawId = text.match(/^[a-zA-Z0-9_-]{20,}$/);
  return rawId ? rawId[0] : '';
}

const fullName = firstValue(['Họ và tên', 'Ho va ten', 'Full name', 'Full Name', 'Name', 'Tên ứng viên']);
const email = firstValue(['Email', 'Email address', 'Địa chỉ email']);
const phone = firstValue(['Số điện thoại', 'So dien thoai', 'Phone', 'Phone number']);
const position = firstValue(['Vị trí ứng tuyển', 'Vi tri ung tuyen', 'Position', 'Role'], 'Chưa xác định');
const cvUrl = firstValue(['CV', 'File CV', 'CV file', 'Upload CV', 'Tải CV', 'Resume']);
const jdFromForm = firstValue(['JD tuyển dụng', 'JD tuyen dung', 'Job Description', 'JD', 'Yêu cầu tuyển dụng']);
const source = firstValue(['Nguồn ứng viên', 'Source', 'Kênh ứng tuyển'], 'Google Form');

const cvFileId = extractDriveFileId(cvUrl);
if (!fullName || !email || !cvFileId) {
  throw new Error(`Thiếu dữ liệu bắt buộc. fullName=${fullName}, email=${email}, cvFileId=${cvFileId}. Kiểm tra tên cột Form và link CV.`);
}

const jdText = jdFromForm || $vars.RECRUITMENT_JD_TEXT || '';
if (!jdText) {
  throw new Error('Thiếu JD tuyển dụng. Điền cột "JD tuyển dụng" trong Form hoặc tạo n8n variable RECRUITMENT_JD_TEXT.');
}

const candidateId = `CAND-${Date.now()}`;

return [{
  json: {
    candidate_id: candidateId,
    full_name: fullName,
    email,
    phone,
    position,
    cv_url: cvUrl,
    cv_file_id: cvFileId,
    source,
    jd_text: jdText.slice(0, 25000),
    form_timestamp: firstValue(['Timestamp', 'Dấu thời gian'], ''),
    received_at: new Date().toISOString(),
    original_form_row: row
  }
}];

const raw = $input.first().json;
const candidate = $('⚙️ Chuẩn Hóa Form & Lấy CV File ID').first().json;

const cvText = String(raw.body || raw.data || raw.text || raw || '').trim();
if (!cvText || cvText.length < 50) {
  throw new Error('Không trích xuất được text từ CV hoặc CV quá ngắn. Kiểm tra file PDF/DOCX và quyền Google Drive.');
}

const prompt = `Bạn là Senior Technical Recruiter. Hãy đánh giá ứng viên dựa trên thông tin Google Form, nội dung CV và JD tuyển dụng.

Yêu cầu output: chỉ trả JSON hợp lệ, không markdown wrapper, theo schema:
{
  "candidate_name": "",
  "position": "",
  "overall_score": 0,
  "classification": "excellent|good|average|reject",
  "recommendation": "shortlist|consider|hold|reject",
  "summary_vi": "Tóm tắt 2-3 câu bằng tiếng Việt",
  "strengths": [""],
  "weaknesses": [""],
  "matched_requirements": [""],
  "missing_requirements": [""],
  "risk_flags": [""],
  "suggested_interview_questions": [""],
  "next_step_vi": "",
  "reasoning_vi": ""
}

Quy tắc phân loại:
- excellent: overall_score >= 85, match rất mạnh với JD, nên ưu tiên liên hệ ngay.
- good: 70-84, phù hợp phần lớn, nên cân nhắc phỏng vấn.
- average: 50-69, có tiềm năng nhưng thiếu yêu cầu quan trọng.
- reject: < 50, không phù hợp JD.

Không bịa kinh nghiệm không có trong CV. Nếu CV thiếu dữ liệu, ghi vào missing_requirements hoặc risk_flags.

<job_description>
${candidate.jd_text}
</job_description>

<form_info>
Candidate ID: ${candidate.candidate_id}
Name: ${candidate.full_name}
Email: ${candidate.email}
Phone: ${candidate.phone}
Position: ${candidate.position}
Source: ${candidate.source}
</form_info>

<cv_text>
${cvText.slice(0, 60000)}
</cv_text>`;

return [{
  json: {
    ...candidate,
    cv_text: cvText.slice(0, 60000),
    cv_text_chars: Math.min(cvText.length, 60000),
    cv_text_truncated: cvText.length > 60000,
    ai_prompt: prompt
  }
}];

