const response = $input.first().json;
const candidate = $('📝 Tạo Prompt Đánh Giá CV').first().json;

let parsed;
try {
  const text = response.choices?.[0]?.message?.content || '';
  const clean = text.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  parsed = JSON.parse(clean);
} catch (error) {
  throw new Error(`Không parse được DeepSeek JSON: ${error.message}. Raw: ${JSON.stringify(response).slice(0, 500)}`);
}

const score = Math.max(0, Math.min(100, Number(parsed.overall_score) || 0));
let classification = String(parsed.classification || '').toLowerCase();
if (!['excellent', 'good', 'average', 'reject'].includes(classification)) {
  classification = score >= 85 ? 'excellent' : score >= 70 ? 'good' : score >= 50 ? 'average' : 'reject';
}

const recommendation = parsed.recommendation || (classification === 'excellent' ? 'shortlist' : classification === 'good' ? 'consider' : classification === 'average' ? 'hold' : 'reject');
const isExcellent = classification === 'excellent' || score >= 85;

const row = {
  'Candidate ID': candidate.candidate_id,
  'Received At': candidate.received_at,
  'Name': candidate.full_name,
  'Email': candidate.email,
  'Phone': candidate.phone,
  'Position': candidate.position,
  'Source': candidate.source,
  'CV URL': candidate.cv_url,
  'Score': score,
  'Classification': classification,
  'Recommendation': recommendation,
  'Summary': parsed.summary_vi || '',
  'Strengths': Array.isArray(parsed.strengths) ? parsed.strengths.join('\n') : '',
  'Weaknesses': Array.isArray(parsed.weaknesses) ? parsed.weaknesses.join('\n') : '',
  'Matched Requirements': Array.isArray(parsed.matched_requirements) ? parsed.matched_requirements.join('\n') : '',
  'Missing Requirements': Array.isArray(parsed.missing_requirements) ? parsed.missing_requirements.join('\n') : '',
  'Risk Flags': Array.isArray(parsed.risk_flags) ? parsed.risk_flags.join('\n') : '',
  'Interview Questions': Array.isArray(parsed.suggested_interview_questions) ? parsed.suggested_interview_questions.join('\n') : '',
  'Next Step': parsed.next_step_vi || '',
  'Reasoning': parsed.reasoning_vi || '',
  'AI Raw JSON': JSON.stringify(parsed),
  'Processed At': new Date().toISOString()
};

const telegramMessage = `🌟 <b>ỨNG VIÊN EXCELLENT</b>
━━━━━━━━━━━━━━━━━━━━

👤 <b>${candidate.full_name}</b>
🎯 Vị trí: ${candidate.position}
📊 Score: <b>${score}/100</b>
📌 Recommendation: <b>${recommendation}</b>

<b>Tóm tắt:</b>
${parsed.summary_vi || ''}

<b>Điểm mạnh:</b>
${(parsed.strengths || []).slice(0, 4).map((s, i) => `${i + 1}. ${s}`).join('\n')}

📧 ${candidate.email}
📞 ${candidate.phone || '(chưa có)'}
🔗 CV: ${candidate.cv_url}`;

return [{
  json: {
    ...candidate,
    ai_result: parsed,
    score,
    classification,
    recommendation,
    is_excellent: isExcellent,
    tracking_row: row,
    telegram_message: telegramMessage
  }
}];
